SELECT DISTINCT bond_type 
FROM bond 
WHERE molecule_id BETWEEN 'TR000' AND 'TR050';

SELECT name
FROM cards
WHERE faceConvertedManaCost = (SELECT MAX(faceConvertedManaCost) FROM cards);

SELECT DISTINCT name, colors
FROM cards
WHERE setCode = 'OGW';

SELECT SUM(CAST(REPLACE(manaCost, '{', '') AS REAL)) AS total_mana_cost
FROM cards
WHERE artist = 'Rob Alexander';

SELECT code 
FROM sets 
WHERE releaseDate = '2007-07-13';

SELECT name 
FROM cards 
WHERE borderColor = 'black' AND isFullArt = 1;

SELECT COUNT(*) 
FROM users 
WHERE LastAccessDate > '2014-09-01 00:00:00';

SELECT Id, OwnerUserId 
FROM posts 
WHERE Score > 60;

SELECT COUNT(AcceptedAnswerId) 
FROM posts 
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT 
    (SELECT COUNT(*) FROM posts WHERE OwnerUserId = (SELECT Id FROM users ORDER BY CreationDate DESC LIMIT 1)) AS PostCount,
    (SELECT COUNT(*) FROM comments WHERE UserId = (SELECT Id FROM users ORDER BY CreationDate DESC LIMIT 1)) AS CommentCount;

SELECT COUNT(*) 
FROM superhero 
WHERE publisher_id IS NULL;

SELECT COUNT(driverId) 
FROM results 
WHERE raceId = 18;

SELECT location, country, lat, lng 
FROM circuits 
WHERE name = 'Hungaroring';

SELECT player_name, height
FROM Player
WHERE height = (SELECT MAX(height) FROM Player);

SELECT player_name 
FROM Player 
WHERE (STRFTIME('%J', 'now') - STRFTIME('%J', birthday)) / 365.25 >= 35;
